58	/**
59	 * As-is baseline evidence for SFCC-681 (TSD-SFCC-681, "MRT Application Topology").
60	 *
61	 * The first two tests exercise the real SSR handler functions rather than stand-ins, so the
62	 * TSD's Problem Statement rests on reproducible evidence rather than assertion. The third
63	 * needs no handler: it demonstrates a property of Node's event loop itself.
64	 *
65	 * These document CURRENT behaviour. The first two are expected to change once the safeguards
66	 * in the TSD's §5 are implemented, and should then be updated to assert the fixed behaviour
67	 * rather than deleted. The third documents a permanent property of any single-process model
68	 * and is expected to keep passing unchanged.
69	 *
70	 * Every fetch is mocked; nothing here contacts a real network endpoint.
71	 */
72	describe('SSR shared-process blast radius (SFCC-681 as-is baseline)', () => {
73	  beforeEach(() => {
74	    vi.stubEnv('MARKETING_CLOUD_CLIENT_ID', 'test-client-id');
75	    vi.stubEnv('MARKETING_CLOUD_CLIENT_SECRET', 'test-client-secret');
76	    vi.stubEnv('MARKETING_CLOUD_SUBDOMAIN', 'test-subdomain');
77	
78	    // getConfig returns the full PWA Kit runtime config; only the fields these two
79	    // handlers actually read are stubbed here.
80	    vi.mocked(getConfig).mockReturnValue({
81	      app: {
82	        sfPayments: { metadataUrl: PAYMENTS_URL },
83	        login: { resetPassword: { landingPath: '/reset-password' }, passwordless: {} },
84	      },
85	    } as ReturnType<typeof getConfig>);
86	
87	    vi.stubGlobal(
88	      'fetch',
89	      vi.fn((input: string | URL) => {
90	        const href = String(input);
91	        // Each branch stubs only the Response members the handlers touch: ok, status, json.
92	        if (href.includes(PAYMENTS_HOST)) {
93	          return Promise.resolve({ ok: true, json: () => Promise.resolve({ paymentMethodTypes: {} }) } as Response);
94	        }
95	        // Note: marketingCloud.ts caches its access token at module scope, so this auth
96	        // branch is only reached by whichever test runs first. Later tests reuse the cached
97	        // token and go straight to the send branch below. That does not affect what these
98	        // tests assert, but any future assertion on token-exchange behaviour would be
99	        // order-dependent and should reset module state first.
100	        if (href.includes(MARKETING_CLOUD_AUTH_HOST)) {
101	          return Promise.resolve({ ok: true, json: () => Promise.resolve({ access_token: 'fake-token' }) } as Response);
102	        }
103	        if (href.includes(MARKETING_CLOUD_REST_HOST)) {
104	          // Marketing Cloud's send-email endpoint is down.
105	          return Promise.resolve({ ok: false, status: 503 } as Response);
106	        }
107	        return Promise.reject(new Error(`Unexpected fetch in test: ${href}`));
108	      }),
109	    );
110	  });
111	
112	  afterEach(() => {
113	    vi.unstubAllGlobals();
114	    vi.unstubAllEnvs();
115	    vi.clearAllMocks();
116	  });
117	
118	  test('one integration rejects uncaught while a sibling catches its own failure and responds', async () => {
119	    const paymentsRes = createMockRes();
120	    const magicLinkRes = createMockRes();
121	
122	    // Both run concurrently, and allSettled reports each outcome independently of the other.
123	    // The asymmetry is the finding: sendMagicLinkEmail has no try/catch around its Marketing
124	    // Cloud call, so it rejects out of the module, while paymentMetadataHandler (and
125	    // jwksCaching) catch their own fetch failures and convert them into HTTP responses.
126	    const [paymentsOutcome, magicLinkOutcome] = await Promise.allSettled([
127	      paymentMetadataHandler({}, paymentsRes),
128	      sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template'),
129	    ]);
130	
131	    expect(magicLinkOutcome.status).toBe('rejected');
132	    expect(paymentsOutcome.status).toBe('fulfilled');
133	    expect(paymentsRes.body).toEqual(expect.objectContaining({ paymentMethodTypes: {} }));
134	  });
135	
136	  test('the shipped route shape leaves the request unanswered when its integration fails', async () => {
137	    const magicLinkRes = createMockRes();
138	
139	    // The real ssr.js route handlers never await or catch this call, so the only thing
140	    // between the rejection and an undetected failure is pwa-kit-runtime's own global
141	    // handler (build-remote-server.js registers process.on('unhandledRejection',
142	    // catchAndLog), which logs and nothing more). Registering an equivalent listener here
143	    // reproduces that real safety net, lets the test assert the rejection genuinely goes
144	    // unhandled by application code, and stops Vitest reporting it as a stray
145	    // run-failing error.
146	    let capturedRejection: unknown;
147	    const onUnhandledRejection = (reason: unknown) => {
148	      capturedRejection = reason;
149	    };
150	    process.once('unhandledRejection', onUnhandledRejection);
151	
152	    try {
153	      // Reproduces the floating-promise shape of the shipped call sites in ssr.js, where
154	      // sendMagicLinkEmail is invoked inside a .then() callback without being returned,
155	      // awaited or chained.
156	      //
157	      // One link is deliberately elided: the real chain begins with
158	      // validateSlasCallbackToken(token).then(...), and that function throws on an invalid
159	      // or expired token. So the shipped code has a SECOND unobserved rejection source that
160	      // this test does not cover, and which a fix targeting only sendMagicLinkEmail would
161	      // not close. See TSD §5.2.
162	      //
163	      // `void` marks the promises as deliberately unobserved for the linter only; it
164	      // attaches no handler and leaves the behaviour under test unchanged.
165	      void Promise.resolve().then(() => {
166	        void sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');
167	      });
168	
169	      // Node reports unhandled rejections on a macrotask boundary, so poll rather than
170	      // sleeping for a fixed duration.
171	      await vi.waitFor(
172	        () => {
173	          expect(capturedRejection).toBeInstanceOf(Error);
174	        },
175	        { timeout: REJECTION_SETTLE_TIMEOUT_MS, interval: 10 },
176	      );
177	      expect((capturedRejection as Error).message).toMatch(/Marketing Cloud/i);
178	
179	      // The other half of the finding: the shopper is told nothing at all. The framework's
180	      // handler only logs, and nothing in that path touches this response. The request is
181	      // left to run out MRT's execution ceiling and return a generic 502.
182	      // eslint-disable-next-line @typescript-eslint/unbound-method -- plain vi.fn() mocks with no `this` dependency; standard Vitest call-count assertion.
183	      expect(magicLinkRes.send).not.toHaveBeenCalled();
184	      // eslint-disable-next-line @typescript-eslint/unbound-method -- see above
185	      expect(magicLinkRes.json).not.toHaveBeenCalled();
186	      // eslint-disable-next-line @typescript-eslint/unbound-method -- see above
187	      expect(magicLinkRes.status).not.toHaveBeenCalled();
188	    } finally {
189	      process.removeListener('unhandledRejection', onUnhandledRejection);
190	    }
191	  });
192	
193	  test('a synchronous CPU-bound operation blocks unrelated concurrent work', async () => {
194	    // Nothing is mocked here. This is a property of Node's single-threaded event loop
195	    // rather than of any integration's code, and it is not addressable by connection
196	    // pools, which govern sockets rather than who holds the JS thread. It therefore
197	    // documents a permanent trade-off of the single-application model rather than a
198	    // defect to be fixed.
199	    let fastResolvedAt = 0;
200	    const start = Date.now();
201	
202	    const fastRequest = Promise.resolve().then(() => {
203	      fastResolvedAt = Date.now();
204	    });
205	
206	    const blockUntil = Date.now() + BLOCK_MS;
207	    while (Date.now() < blockUntil) {
208	      // Busy-wait, standing in for a heavy synchronous operation such as a large
209	      // JSON.parse or an expensive regex inside an integration handler.
210	    }
211	
212	    await fastRequest;
213	    const fastRequestDelay = fastResolvedAt - start;
214	
215	    // The fast work should resolve almost immediately. Instead it waits out the entire
216	    // blocking operation, because both share one event loop. The upper bound guards
217	    // against the assertion passing for an unrelated reason.
218	    expect(fastRequestDelay).toBeGreaterThanOrEqual(BLOCK_MS - TIMER_TOLERANCE_MS);
219	    expect(fastRequestDelay).toBeLessThan(BLOCK_MS * 2);
220	  });
221	});
